let workspaceResult=null;
async function postAnalysis(path,body){const response=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});let data;try{data=await response.json();}catch{throw new Error('서버 응답을 읽지 못했습니다. 잠시 후 다시 시도하세요.');}if(!response.ok){const detail=Array.isArray(data.detail)?data.detail.map(d=>d.msg).join(' · '):data.detail;throw new Error(detail||'분석 요청을 처리하지 못했습니다.');}return data;}
function saveCsv(records,name){if(!records.length)return;const keys=Object.keys(records[0]),quote=v=>'"'+String(v??'').replaceAll('"','""')+'"';const text='\ufeff'+[keys,...records.map(r=>keys.map(k=>r[k]))].map(row=>row.map(quote).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([text],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function renderWorkspace(){
 const field=state.field,queries=Object.fromEntries(Object.entries(DATA.papers).map(([k,v])=>[k,v.manifest.query]));
 $('main').innerHTML=`<div class="eyebrow">03 / YOUR DATA</div><h1>내 자료로 분석하고 새 논문을 수집합니다</h1><p class="intro">기업 원문 CSV를 넣어 같은 분야끼리 비교하거나, 원하는 두 기간의 실제 논문을 찾아 연구 내용을 살펴보세요.</p><div class="notice">입력 자료와 수집 결과는 해당 요청을 처리하는 데 사용합니다. 공용 표본을 덮어쓰거나 다른 사용자에게 공개하지 않습니다. 결과를 보관하려면 CSV로 내려받으세요.</div><section class="panel"><h2>기업 원문 CSV 분석</h2><p>필수 열: company(기업명), sector(산업 분야), text(원문), source_url(출처 주소), report_id(보고서 ID), collected_at(수집 시각), section(원문 절). 같은 분야의 서로 다른 기업이 최소 4개 필요합니다.</p><form id="upload-form"><div class="controls"><label>기업 원문 CSV · 최대 2MB / 60개 기업<input id="upload-file" type="file" accept=".csv,text/csv" required></label><label>자동 묶음 수<input id="upload-k" type="number" min="2" max="6" value="3" required></label></div><button class="action-button" type="submit">업로드한 원문 분석</button></form><p id="upload-status" role="status" class="note"></p>${download('companies','실제 기업 CSV 형식 참고')}</section><section class="panel"><h2>실제 논문 수집</h2><form id="collect-form"><div class="controls">${select('collect-field','기술 분야',Object.keys(DATA.papers),field)}${select('collect-route','수집 경로',['OpenAlex · arXiv 원문만','arXiv 직접 API'],'OpenAlex · arXiv 원문만')}</div><label>검색 조건<textarea id="collect-query" rows="3" maxlength="400" required>${esc(queries[field])}</textarea></label><div class="controls"><label>기간 A 시작<input id="start-a" type="date" value="2025-01-01" required></label><label>기간 A 끝<input id="end-a" type="date" value="2025-08-31" required></label><label>기간 B 시작<input id="start-b" type="date" value="2026-01-01" required></label><label>기간 B 끝<input id="end-b" type="date" value="2026-08-31" required></label><label>기간별 최신순 수집 상한<input id="collect-limit" type="number" min="2" max="60" value="30" required></label></div><button class="action-button" type="submit">논문 수집하고 내용 분석</button></form><p id="collect-status" role="status" class="note"></p>${note('두 기간이 겹치지 않도록 설정하세요. 제공처의 요청 제한이나 인증 요구가 있으면 이유를 표시합니다. 자동으로 만든 논문으로 채우지 않습니다. 검색 조건은 선택한 제공처의 문법을 따릅니다.')}</section><div id="workspace-output"></div>`;
 bindSelect('collect-field',value=>{$('collect-query').value=queries[value];});bindSelect('collect-route',value=>{$('collect-query').value=value.startsWith('arXiv')?'all:"neural network"':queries[$('collect-field').value];});
 $('upload-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;$('upload-status').textContent='원문을 확인하고 분야별 유사도를 계산하고 있습니다…';try{const file=$('upload-file').files[0];if(!file)throw new Error('기업 CSV를 선택하세요.');if(file.size>2_000_000)throw new Error('2MB 이하의 CSV를 선택하세요.');const result=await postAnalysis('/api/companies/analyze',{csv_text:await file.text(),clusters:Number($('upload-k').value)});workspaceResult=result;renderUploadResult(result);$('upload-status').textContent=result.rows+'개 기업 처리 완료. '+result.source;}catch(error){$('upload-status').textContent=error.message;}finally{button.disabled=false;}});
 $('collect-form').addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;$('collect-status').textContent='제공처에서 실제 논문을 수집하고 있습니다…';try{const result=await postAnalysis('/api/papers/collect',{field:$('collect-field').value,query:$('collect-query').value,start_a:$('start-a').value,end_a:$('end-a').value,start_b:$('start-b').value,end_b:$('end-b').value,per_period:Number($('collect-limit').value),route:$('collect-route').value.startsWith('OpenAlex')?'openalex':'arxiv'});state.field=result.field;$('workspace-output').innerHTML='<div id="collected-insights"></div><section class="panel"><h2>이번 수집 기록과 원문</h2><button id="save-collected" class="action-button">이번 수집 결과 CSV 다운로드</button><div id="collection-records"></div><div id="collected-originals"></div></section>';renderResearchInsights($('collected-insights'),{records:result.records});$('collection-records').innerHTML=table(['기간','시작일','종료일','수집 시점','검색 일치 수','분석 표본 수'],result.manifest.periods.map(p=>[esc(p.period),esc(p.start_date),esc(p.end_date),esc(p.collected_at),String(p.total_matches),String(p.retained)]));$('collected-originals').innerHTML=result.records.map(paperDetail).join('');$('save-collected').addEventListener('click',()=>saveCsv(result.records,'collected-papers.csv'));$('collect-status').textContent=result.records.length+'편을 수집했습니다. 아래에서 근거 초록과 분석 조건을 확인하세요.';}catch(error){$('collect-status').textContent=error.message;}finally{button.disabled=false;}});
}
function renderUploadResult(result){const host=$('workspace-output');host.innerHTML=`<section class="panel"><h2>업로드한 기업 ${result.rows}개 · 분야별 분석</h2>${note(result.source)}<div class="controls">${select('uploaded-sector','분석 결과를 볼 분야',result.groups.map(g=>g.sector),result.groups[0].sector)}</div><div id="uploaded-group"></div></section>`;const show=sector=>{const g=result.groups.find(g=>g.sector===sector);if(g.error){$('uploaded-group').innerHTML=note(g.error);return;}$('uploaded-group').innerHTML=`<h3>${esc(g.sector)} · ${g.count}개 기업</h3><div id="uploaded-matrix" class="chart"></div>${note('같은 분야 문서만으로 계산한 표현의 유사도입니다. 원문과 출처의 진위는 사용자가 확인해야 합니다.')}<div class="controls">${select('uploaded-company','원문을 볼 기업',g.companies,g.companies[0])}</div><div id="uploaded-original"></div>`;chart('uploaded-matrix',[{type:'heatmap',x:g.companies,y:g.companies,z:g.similarity,zmin:0,zmax:1,colorscale:[[0,'#f0f7f4'],[1,palette[0]]],hovertemplate:'%{y} ↔ %{x}<br>%{z:.3f}<extra></extra>'}],{height:Math.max(380,g.count*28),xaxis:{tickangle:-45,automargin:true},yaxis:{automargin:true}});const original=name=>{const record=g.records.find(r=>r.company===name);$('uploaded-original').innerHTML=`<h3>${esc(name)}</h3>${link(record.source_url)}<div class="source-reader">${record.text.split(/\n+/).filter(Boolean).map(p=>`<p>${esc(p)}</p>`).join('')}</div>`;};bindSelect('uploaded-company',original);original(g.companies[0]);};bindSelect('uploaded-sector',show);show(result.groups[0].sector);}
